package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;
import com.greatleyposhley.professy.entities.Issues;import com.greatleyposhley.professy.repositories.*;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;import static com.greatleyposhley.professy.collaboration.DeliveryRules.*;
@RestController @RequestMapping("/api/retrospectives")
public class SprintRetrospectives {
 final WorkAccess access;final DeliveryOperations ops;final ProjectsRepository projects;final IssuesRepository issues;
 public SprintRetrospectives(WorkAccess access,DeliveryOperations ops,ProjectsRepository projects,IssuesRepository issues){this.access=access;this.ops=ops;this.projects=projects;this.issues=issues;}
 long org(){return access.actor().getOrgId();}
 Map<String,Object> sprint(long id){access.require("TICKETS.READ");var rows=access.jdbc.queryForList("SELECT * FROM sprints WHERE id=? AND org_id=?",id,org());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Sprint not found");access.project(number(rows.getFirst().get("project_id")));return rows.getFirst();}
 boolean manage(){return access.admin(access.actor())||access.policy.can(access.actor(),"PROJECTS.UPDATE");}
 void collecting(long id){var sprint=sprint(id);access.jdbc.update("INSERT IGNORE INTO sprint_retrospectives(sprint_id,org_id,project_id,summary,updated_by) VALUES(?,?,?,'',?)",id,org(),sprint.get("project_id"),access.actor().getId());var meeting=access.jdbc.queryForMap("SELECT state FROM sprint_retrospectives WHERE sprint_id=? AND org_id=? FOR UPDATE",id,org());if("CLOSED".equals(meeting.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Retrospective is closed");}

 @GetMapping public Object list(@RequestParam long projectId){access.require("TICKETS.READ");access.project(projectId);return access.jdbc.queryForList("SELECT s.id,s.name,s.status,COALESCE(r.state,'COLLECTING') AS retrospectiveState,(SELECT COUNT(*) FROM retrospective_entries e WHERE e.sprint_id=s.id AND e.org_id=s.org_id) AS entryCount FROM sprints s LEFT JOIN sprint_retrospectives r ON r.sprint_id=s.id AND r.org_id=s.org_id WHERE s.org_id=? AND s.project_id=? ORDER BY s.id DESC LIMIT 200",org(),projectId);}
 @GetMapping("/{id}") public Object get(@PathVariable long id){var s=sprint(id);var meta=access.jdbc.queryForList("SELECT * FROM sprint_retrospectives WHERE sprint_id=? AND org_id=?",id,org());var entries=access.jdbc.queryForList("SELECT e.*,CONCAT_WS(' ',u.first_name,u.last_name) authorName,CONCAT_WS(' ',o.first_name,o.last_name) ownerName,(SELECT COUNT(*) FROM retrospective_votes v WHERE v.entry_id=e.id) AS votes,EXISTS(SELECT 1 FROM retrospective_votes v WHERE v.entry_id=e.id AND v.user_id=?) AS voted FROM retrospective_entries e JOIN user_account u ON u.id=e.author_id LEFT JOIN user_account o ON o.id=e.owner_id WHERE e.org_id=? AND e.sprint_id=? ORDER BY votes DESC,e.id",access.actor().getId(),org(),id);return Map.of("sprint",s,"meeting",meta.isEmpty()?Map.of("state","COLLECTING","summary","","revision",0):meta.getFirst(),"entries",entries,"canManage",manage(),"userId",access.actor().getId());}
 @PutMapping("/{id}") @Transactional public Object update(@PathVariable long id,@RequestBody Map<String,Object>b){var s=sprint(id);if(!manage())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Project management permission is required");String state=choice(b.get("state"),Set.of("COLLECTING","DISCUSSING","CLOSED")),summary=text(b.get("summary"),12000);long revision=number(b.get("revision"));var rows=access.jdbc.queryForList("SELECT * FROM sprint_retrospectives WHERE sprint_id=? AND org_id=? FOR UPDATE",id,org());if(rows.isEmpty()){if(revision!=0)throw TicketExecution.conflict();access.jdbc.update("INSERT INTO sprint_retrospectives(sprint_id,org_id,project_id,state,summary,updated_by) VALUES(?,?,?,?,?,?)",id,org(),s.get("project_id"),state,summary,access.actor().getId());}else if(access.jdbc.update("UPDATE sprint_retrospectives SET state=?,summary=?,revision=revision+1,updated_by=?,updated_at=CURRENT_TIMESTAMP(6) WHERE sprint_id=? AND org_id=? AND revision=?",state,summary,access.actor().getId(),id,org(),revision)!=1)throw TicketExecution.conflict();return get(id);}
 @PostMapping("/{id}/entries") @Transactional public Object add(@PathVariable long id,@RequestBody Map<String,Object>b){sprint(id);collecting(id);String category=choice(b.get("category"),Set.of("WENT_WELL","IMPROVE","ACTION"));long entry=ops.insert("INSERT INTO retrospective_entries(sprint_id,org_id,category,body,author_id,owner_id,due_date) VALUES(?,?,?,?,?,?,?)",id,org(),category,required(b.get("body"),6000),access.actor().getId(),owner(b.get("ownerId")),date(b.get("dueDate")));return Map.of("id",entry);}
 Object owner(Object value){long id=number(value);if(id==0)return null;if(access.jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE id=? AND org_id=? AND is_active=1",Integer.class,id,org())!=1)throw new IllegalArgumentException("Choose an active organization member");return id;}
 Object date(Object value){String d=text(value,10);return d.isEmpty()?null:java.time.LocalDate.parse(d);}
 Map<String,Object> entry(long sprint,long entry){var rows=access.jdbc.queryForList("SELECT * FROM retrospective_entries WHERE id=? AND sprint_id=? AND org_id=? FOR UPDATE",entry,sprint,org());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Entry not found");return rows.getFirst();}
 @PutMapping("/{id}/entries/{entryId}") @Transactional public Object edit(@PathVariable long id,@PathVariable long entryId,@RequestBody Map<String,Object>b){sprint(id);collecting(id);var e=entry(id,entryId);if(number(e.get("author_id"))!=access.actor().getId()&&!manage())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the author or facilitator can edit this entry");access.jdbc.update("UPDATE retrospective_entries SET body=?,owner_id=?,due_date=? WHERE id=? AND org_id=?",required(b.get("body"),6000),owner(b.get("ownerId")),date(b.get("dueDate")),entryId,org());return get(id);}
 @PostMapping("/{id}/entries/{entryId}/vote") @Transactional public Object vote(@PathVariable long id,@PathVariable long entryId){sprint(id);collecting(id);entry(id,entryId);if(access.jdbc.update("DELETE FROM retrospective_votes WHERE entry_id=? AND user_id=?",entryId,access.actor().getId())==0)access.jdbc.update("INSERT INTO retrospective_votes VALUES(?,?)",entryId,access.actor().getId());return get(id);}
 @PostMapping("/{id}/entries/{entryId}/ticket") @Transactional public Object action(@PathVariable long id,@PathVariable long entryId){var s=sprint(id);collecting(id);access.require("TICKETS.CREATE");var e=entry(id,entryId);if(!"ACTION".equals(e.get("category")))throw new IllegalArgumentException("Choose an action entry");if(!manage()&&number(e.get("author_id"))!=access.actor().getId())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the author or facilitator can create this action ticket");if(e.get("action_issue_id")!=null)return Map.of("issueId",e.get("action_issue_id"));var issue=new Issues();issue.setOrgId(org());issue.setProject(projects.findById(number(s.get("project_id"))).orElseThrow());issue.setUser(access.actor());issue.setCreator(access.actor());issue.setReporter(access.actor());issue.setTitle("Retro action: "+e.get("body").toString().substring(0,Math.min(220,e.get("body").toString().length())));issue.setDescription("Sprint retrospective: "+s.get("name")+"\n\n"+e.get("body")+"\nOwner: "+Objects.toString(e.get("owner_id"),"Unassigned")+"\nDue: "+Objects.toString(e.get("due_date"),"Not set"));issue.setIssueCode("RETRO-"+UUID.randomUUID().toString().substring(0,16));issue.setStatus("BACKLOG");issues.saveAndFlush(issue);if(e.get("owner_id")!=null)access.jdbc.update("UPDATE issues SET assignee_user_id=? WHERE id=?",e.get("owner_id"),issue.getId());access.jdbc.update("UPDATE retrospective_entries SET action_issue_id=? WHERE id=?",issue.getId(),entryId);return Map.of("issueId",issue.getId());}
}
